#include <math.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Scaled forward-backward for a small fixed-state categorical HMM. */
double forward_backward(int length, int states, const int32_t *sequence,
                        const double *emissions, const double *initial,
                        const double *transitions, double *posterior) {
    if (length < 1 || states < 1) return NAN;
    double *alpha = calloc((size_t)length * states, sizeof(double));
    double *scale = calloc(length, sizeof(double));
    double *back = calloc(states, sizeof(double));
    double *work = calloc(states, sizeof(double));
    if (!alpha || !scale || !back || !work) {
        free(alpha);
        free(scale);
        free(back);
        free(work);
        return NAN;
    }
    double log_likelihood = 0.0;
    for (int t = 0; t < length; ++t) {
        const double *emit = emissions + (size_t)sequence[t] * states;
        double *current = alpha + (size_t)t * states;
        if (!t) {
            memcpy(current, initial, states * sizeof(double));
        } else {
            const double *previous = current - states;
            for (int last = 0; last < states; ++last) {
                const double *transition = transitions + (size_t)last * states;
                for (int next = 0; next < states; ++next)
                    current[next] += previous[last] * transition[next];
            }
        }
        for (int k = 0; k < states; ++k) {
            current[k] *= emit[k];
            scale[t] += current[k];
        }
        if (!(scale[t] > 0.0)) {
            log_likelihood = -INFINITY;
            break;
        }
        log_likelihood += log(scale[t]);
        for (int k = 0; k < states; ++k)
            current[k] /= scale[t];
    }
    if (posterior && isfinite(log_likelihood)) {
        for (int k = 0; k < states; ++k) back[k] = 1.0;
        for (int t = length - 1; t >= 0; --t) {
            const double *current = alpha + (size_t)t * states;
            double *out = posterior + (size_t)t * states;
            double total = 0.0;
            for (int k = 0; k < states; ++k) {
                out[k] = current[k] * back[k];
                total += out[k];
            }
            for (int k = 0; k < states; ++k) out[k] /= total;
            if (!t) break;
            const double *emit = emissions + (size_t)sequence[t] * states;
            for (int k = 0; k < states; ++k) work[k] = back[k] * emit[k] / scale[t];
            for (int previous = 0; previous < states; ++previous) {
                const double *transition = transitions + (size_t)previous * states;
                double z = 0.0;
                for (int next = 0; next < states; ++next)
                    z += transition[next] * work[next];
                back[previous] = z;
            }
        }
    }
    free(alpha);
    free(scale);
    free(back);
    free(work);
    return log_likelihood;
}
